{"path": "/tmp/sv-cac1e62699fb4a6281e1a1e80a6f64da/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="page-btn"
            disabled="@(CurrentPage <= 1)"
            @onclick="() => GoToPage(CurrentPage - 1)">
        Previous
    </button>

    @foreach (var page in PageNumbers)
    {
        <button class="page-btn @(page == CurrentPage ? "active" : "")"
                @onclick="() => GoToPage(page)">
            @page
        </button>
    }

    <button class="page-btn"
            disabled="@(CurrentPage >= TotalPages)"
            @onclick="() => GoToPage(CurrentPage + 1)">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private IEnumerable<int> PageNumbers => Enumerable.Range(1, TotalPages);

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}
"}

