.catalog-filters {
    padding: 1.5rem;
    background-color: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
}

.catalog-filters h2 {
    margin: 0 0 1rem;
    font-size: 1.2rem;
}

.filter-section {
    margin-bottom: 1.5rem;
}

.filter-section h3 {
    margin: 0 0 0.5rem;
    font-size: 0.95rem;
    font-weight: 600;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
    cursor: pointer;
}

.price-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
    font-weight: 500;
}

.price-inputs input {
    padding: 0.4rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    margin-top: 0.2rem;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    background-color: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

.btn-apply:hover {
    background-color: #0b5ed7;
}

.btn-clear {
    padding: 0.5rem 1rem;
    background-color: transparent;
    color: #6c757d;
    border: 1px solid #6c757d;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

.btn-clear:hover {
    background-color: #6c757d;
    color: white;
}

.filter-loading {
    color: #6c757d;
    font-size: 0.85rem;
    font-style: italic;
}

